<script setup lang="ts">import { computed, nextTick, ref, watch } from "vue";import { useI18nStore } from "../stores/i18n";import UiDialog from "./ui/UiDialog.vue";const props=defineProps<{text:string;canPrevious:boolean;canNext:boolean;busy?:boolean}>();const emit=defineEmits<{close:[];slice:[direction:"previous"|"next"|"keep"|"new",offset:number,keepEnd?:number]}>();const i18n=useI18nStore();const textarea=ref<HTMLTextAreaElement|null>(null);const offset=ref(Math.max(1,Math.min(props.text.length-1,Math.floor(props.text.length/2))));const keepEnd=ref<number|null>(null);const before=computed(()=>props.text.slice(0,offset.value).trim());const selected=computed(()=>keepEnd.value===null?"":props.text.slice(offset.value,keepEnd.value).trim());const after=computed(()=>keepEnd.value===null?props.text.slice(offset.value).trim():props.text.slice(keepEnd.value).trim());function capture(){const el=textarea.value;if(!el)return;const start=Math.min(el.selectionStart||0,el.selectionEnd||0);const end=Math.max(el.selectionStart||0,el.selectionEnd||0);if(start>0&&end<props.text.length&&start<end){offset.value=start;keepEnd.value=end}else if(start>0&&start<props.text.length){offset.value=start;keepEnd.value=null}}function apply(direction:"previous"|"next"|"keep"|"new"){if((direction==="keep"||direction==="new")&&keepEnd.value!==null)emit('slice',direction,offset.value,keepEnd.value);else if(direction!=="keep"&&direction!=="new"&&before.value&&after.value)emit('slice',direction,offset.value)}watch(()=>props.text,()=>{offset.value=Math.max(1,Math.min(props.text.length-1,Math.floor(props.text.length/2)));keepEnd.value=null;void nextTick(()=>{textarea.value?.focus();textarea.value?.setSelectionRange(offset.value,offset.value)})},{immediate:true});</script><template><UiDialog :open="true" size="xlarge" :title="i18n.t('pdf_corpus.slice_record','Slice record')" :description="i18n.t('pdf_corpus.slice_record_help','Place the caret where this record should begin or end, then move the misplaced text to the neighboring record. Both records remain in review and the operation can be undone.')" :close-label="i18n.t('ui.close','Close')" @close="emit('close')"><label class="slice-label"><span>{{i18n.t('pdf_corpus.slice_point','Slice point')}}</span><textarea ref="textarea" :value="text" readonly aria-describedby="slice-instructions" @click="capture" @keyup="capture"></textarea></label><p id="slice-instructions" class="instructions">{{i18n.t('pdf_corpus.slice_point_help','Click between characters to choose the boundary. The preview below shows what would move.')}}</p><div class="preview-grid"><article><b>{{i18n.t('pdf_corpus.before_slice','Before slice')}}</b><p>{{before||'—'}}</p></article><article v-if="keepEnd!==null"><b>Keep selected</b><p>{{selected||'—'}}</p></article><article><b>{{i18n.t('pdf_corpus.after_slice','After slice')}}</b><p>{{after||'—'}}</p></article></div><template #footer><div class="slice-actions"><button v-if="keepEnd!==null" class="btn primary" type="button" :disabled="busy||!canPrevious||!canNext||!before||!selected||!after" @click="apply('new')">{{i18n.t('pdf_corpus.create_record_from_selection','Create record from selection')}}</button><button v-if="keepEnd!==null" class="btn" type="button" :disabled="busy||!canPrevious||!canNext||!before||!selected||!after" @click="apply('keep')">Keep selected chunk</button><button v-else class="btn" type="button" :disabled="busy||!canPrevious||!before||!after" @click="apply('previous')">← {{i18n.t('pdf_corpus.move_before_previous','Move before slice to previous record')}}</button><button v-if="keepEnd===null" class="btn primary" type="button" :disabled="busy||!canNext||!before||!after" @click="apply('next')">{{i18n.t('pdf_corpus.move_after_next','Move after slice to next record')}} →</button></div></template></UiDialog></template><style scoped>.slice-label{display:grid;gap:7px;font-weight:750}.slice-label textarea{width:100%;min-height:260px;resize:vertical;padding:14px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text);font:16px/1.65 Georgia,serif}.instructions{margin:0;color:var(--muted);font-size:.875rem;line-height:1.5}.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.preview-grid article{border:1px solid var(--line);border-radius:10px;padding:11px;background:var(--soft);min-width:0}.preview-grid p{margin:7px 0 0;max-height:140px;overflow:auto;white-space:pre-wrap;font-size:.875rem;line-height:1.5}.slice-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}:is(button,textarea):focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:720px){.preview-grid{grid-template-columns:1fr}.slice-actions{flex-direction:column;align-items:stretch}}</style>